import html


def customer_data_control_html(api_version):
    page = r"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="color-scheme" content="dark">
  <title>VaultLink Data Control</title>
  <style>
    :root{--bg:#0c1013;--band:#12181d;--surface:#182129;--field:#080b0e;--line:#35444f;--text:#f5f7f8;--muted:#a8b6bf;--green:#62e58d;--blue:#5ec5ed;--yellow:#ffd166;--red:#ff7d75}
    *{box-sizing:border-box}html{background:var(--bg);color:var(--text);font-family:Segoe UI,Arial,sans-serif;letter-spacing:0}body{margin:0;min-width:0;background:var(--bg)}button,select{font:inherit;letter-spacing:0}header{border-bottom:1px solid var(--line);background:var(--band)}header>div,main,footer>div{width:min(1180px,calc(100% - 32px));margin:auto}header>div{display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:64px}.brand{font-size:1rem;font-weight:800}nav{display:flex;flex-wrap:wrap;gap:8px}nav a{padding:8px 9px;border:1px solid var(--line);border-radius:5px;color:var(--text);font-size:.73rem;font-weight:800;text-decoration:none}main{padding:34px 0 48px}h1{margin:0;font-size:2rem;line-height:1.1}h2{margin:0;font-size:1.25rem}h3{margin:0;font-size:1rem}p{color:var(--muted);line-height:1.5}.lead{max-width:850px;margin:9px 0 0}.privacy{margin:18px 0;padding:14px 16px;border-left:4px solid var(--green);background:var(--band);color:var(--muted);line-height:1.5}.controls{display:grid;grid-template-columns:minmax(210px,1fr) repeat(6,auto);gap:9px;align-items:end;padding:14px;border:1px solid var(--line);background:var(--band)}label,.eyebrow{display:block;margin-bottom:6px;color:var(--yellow);font-size:.69rem;font-weight:800;text-transform:uppercase}select,button{min-height:40px;border:1px solid var(--line);border-radius:5px}select{width:100%;padding:0 11px;background:var(--field);color:var(--text)}button{padding:0 12px;background:#27343e;color:var(--text);font-size:.75rem;font-weight:800;cursor:pointer}button.primary{background:var(--green);color:#041008;border-color:var(--green)}button.export{background:var(--yellow);color:#151000;border-color:var(--yellow)}button:disabled,select:disabled{cursor:not-allowed;opacity:.45}.status{min-height:32px;padding:9px 0;color:var(--muted)}.status.good{color:var(--green)}.status.bad{color:var(--red)}.metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));margin:4px 0 24px;border:1px solid var(--line)}.metric{min-width:0;padding:14px;border-right:1px solid var(--line)}.metric:last-child{border-right:0}.metric span{display:block;color:var(--muted);font-size:.68rem;font-weight:700;text-transform:uppercase}.metric strong{display:block;margin-top:6px;overflow-wrap:anywhere;font-size:1rem}.section{margin-top:26px;padding-top:22px;border-top:1px solid var(--line)}.section-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:13px}.section-head p{max-width:660px;margin:0;text-align:right}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.data-card{display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px;min-width:0;padding:16px;border:1px solid var(--line);border-left:4px solid var(--blue);border-radius:7px;background:var(--surface)}.data-card.reviewed{border-left-color:var(--green)}.data-card input{width:19px;height:19px;margin:2px 0 0;accent-color:var(--green)}.card-top{display:flex;align-items:start;justify-content:space-between;gap:12px}.scope{color:var(--blue);font-size:.68rem;font-weight:800;text-align:right;text-transform:uppercase}.facts{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:12px}.fact{min-width:0;padding:10px;border-top:1px solid var(--line)}.fact strong{display:block;margin-bottom:4px;color:var(--yellow);font-size:.68rem;text-transform:uppercase}.fact span{display:block;color:var(--muted);font-size:.82rem;line-height:1.4;overflow-wrap:anywhere}.flow,.boundaries{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.flow article,.boundary{min-width:0;padding:15px;border:1px solid var(--line);border-radius:7px;background:var(--surface)}.flow article{border-top:3px solid var(--green)}.boundary{border-top:3px solid var(--yellow)}.flow p,.boundary p{margin:7px 0 0;font-size:.88rem}footer{border-top:1px solid var(--line);background:var(--band)}footer>div{padding:20px 0;color:var(--muted);font-size:.82rem;line-height:1.45}@media(max-width:980px){.controls{grid-template-columns:repeat(3,minmax(0,1fr))}.controls>div{grid-column:1/-1}.metrics{grid-template-columns:repeat(3,minmax(0,1fr))}.metric:nth-child(3){border-right:0}.cards{grid-template-columns:1fr}}@media(max-width:620px){header>div{align-items:flex-start;flex-direction:column;padding:14px 0}main{padding-top:24px}h1{font-size:1.65rem}.controls{grid-template-columns:1fr}.controls button{width:100%}.metrics{grid-template-columns:1fr}.metric{border-right:0;border-bottom:1px solid var(--line)}.metric:last-child{border-bottom:0}.section-head{align-items:flex-start;flex-direction:column}.section-head p{text-align:left}.facts,.flow,.boundaries{grid-template-columns:1fr}.card-top{flex-direction:column}.scope{text-align:left}}
  </style>
</head>
<body>
  <header><div><div class="brand">VaultLink Data Control</div><nav><a href="/workspace">WORKSPACE</a><a href="/recovery-kit">KIT</a><a href="/backup-verification">BACKUPS</a><a href="/diagnostics">DIAGNOSTICS</a><a href="/trust">TRUST</a><a href="/privacy">PRIVACY</a><a href="/status">STATUS</a></nav></div></header>
  <main>
    <h1>Know what exists and where it stays</h1>
    <p class="lead">Review VaultLink's fixed data classes, protection boundaries, retention rules, and customer controls without sending an inventory, path, file, account, or local result.</p>
    <div class="privacy">This public workspace cannot inspect a PC. Review progress exists only in the current tab and disappears on reload. A downloaded receipt contains fixed class IDs and public service metadata only.</div>
    <div class="controls">
      <div><label for="scope">Data scope</label><select id="scope" disabled></select></div>
      <button id="reset" type="button" disabled>RESET</button>
      <button id="next" class="primary" type="button" disabled>REVIEW NEXT</button>
      <button id="visible" type="button" disabled>REVIEW VISIBLE</button>
      <button id="copy" type="button" disabled>COPY RECEIPT</button>
      <button id="print" type="button" disabled>PRINT</button>
      <button id="export" class="export" type="button" disabled>EXPORT SAFE JSON</button>
    </div>
    <div id="status" class="status" role="status" aria-live="polite">Loading the fixed public data map...</div>
    <div id="workspace" hidden>
      <div id="metrics" class="metrics"></div>
      <section class="section"><div class="section-head"><div><div class="eyebrow">FIXED DATA MAP</div><h2>Data classes</h2></div><p>Reviewing a class means you read its public boundary. It does not confirm what exists on this PC.</p></div><div id="cards" class="cards"></div></section>
      <section class="section"><div class="section-head"><div><div class="eyebrow">DATA FLOW</div><h2>How information moves</h2></div><p>Every step remains bounded by an explicit local or API action.</p></div><div id="flow" class="flow"></div></section>
      <section class="section"><div class="section-head"><h2>Privacy boundaries</h2><p>The desktop companion adds allowlisted coarse local checks; this page receives none of them.</p></div><div id="boundaries" class="boundaries"></div></section>
      <section class="section"><div class="section-head"><h2>Limitations</h2><p>A data map helps with review, but it is not a forensic inventory or compliance certification.</p></div><div id="limitations" class="boundaries"></div></section>
    </div>
  </main>
  <footer><div>API __API_VERSION__. No browser storage, account, license proof, path, file, customer inventory, or progress submission API is used.</div></footer>
  <script>
    const $=id=>document.getElementById(id);const state={payload:null,scope:"all",reviewed:new Set()};const value=input=>String(input??"");
    function setStatus(message,tone=""){$("status").textContent=message;$('status').className=`status ${tone}`;}function add(parent,tag,text,className=""){const node=document.createElement(tag);node.textContent=value(text);if(className)node.className=className;parent.append(node);return node;}function metric(label,text){const node=document.createElement("div");node.className="metric";add(node,"span",label);add(node,"strong",text);return node;}function scopeLabel(id){return state.payload.scopes.find(item=>item.id===id)?.label||id;}function visibleClasses(){const items=state.payload?.data_classes||[];return state.scope==="all"?items:items.filter(item=>item.scope_id===state.scope);}
    function safeReceipt(){const known=new Set((state.payload?.data_classes||[]).map(item=>item.id));return{schema_version:1,report_type:"VaultLink Privacy-Safe Browser Data Map Receipt",generated_at_utc:new Date().toISOString(),api_version:state.payload.api_version,service_mode:state.payload.service_status.mode,signed_desktop_version:state.payload.signed_release.version||"",selected_scope_id:state.scope,reviewed_class_ids:[...state.reviewed].filter(id=>known.has(id)).sort(),reviewed_count:[...state.reviewed].filter(id=>known.has(id)).length,class_count:known.size,privacy_notice:"No name, contact, license proof, receipt, key, PIN, USB secret, path, filename, file content, local inventory, screenshot, process list, or free-form note is included."};}
    function renderMetrics(){const reviewed=(state.payload.data_classes||[]).filter(item=>state.reviewed.has(item.id)).length;const root=$("metrics");root.replaceChildren();[["API",state.payload.api_version],["Service",state.payload.service_status.mode],["Signed desktop",state.payload.signed_release.version||"Not published"],["Data classes",state.payload.class_count],["Scopes",state.payload.scope_count],["Reviewed",`${reviewed} / ${state.payload.class_count}`]].forEach(row=>root.append(metric(...row)));}
    function renderCards(){const root=$("cards");root.replaceChildren();const items=visibleClasses();items.forEach(item=>{const card=document.createElement("article");card.className=`data-card ${state.reviewed.has(item.id)?"reviewed":""}`;const box=document.createElement("input");box.type="checkbox";box.checked=state.reviewed.has(item.id);box.setAttribute("aria-label",`Review ${item.label}`);box.addEventListener("change",()=>{box.checked?state.reviewed.add(item.id):state.reviewed.delete(item.id);renderCards();});const body=document.createElement("div");const top=document.createElement("div");top.className="card-top";add(top,"h3",item.label);add(top,"div",scopeLabel(item.scope_id),"scope");body.append(top);add(body,"p",item.purpose);const facts=document.createElement("div");facts.className="facts";[["Protection",item.protection],["Retention",item.retention],["Customer control",item.customer_action],["Desktop map",item.desktop_inventory]].forEach(([label,text])=>{const fact=document.createElement("div");fact.className="fact";add(fact,"strong",label);add(fact,"span",text);facts.append(fact);});body.append(facts);card.append(box,body);root.append(card);});renderMetrics();setStatus(`${items.length} fixed data class(es) visible. ${items.filter(item=>state.reviewed.has(item.id)).length} reviewed in this view.`,"good");}
    function render(data){state.payload=data;const select=$("scope");select.replaceChildren();[["all","All scopes"],...data.scopes.map(item=>[item.id,item.label])].forEach(([id,label])=>{const option=document.createElement("option");option.value=id;option.textContent=label;select.append(option);});select.value="all";select.disabled=false;["reset","next","visible","copy","print","export"].forEach(id=>$(id).disabled=false);const flow=$("flow");flow.replaceChildren();data.flow_steps.forEach((item,index)=>{const card=document.createElement("article");add(card,"div",`STEP ${index+1}`,"eyebrow");add(card,"h3",item.label);add(card,"p",item.detail);flow.append(card);});[["boundaries",data.privacy_boundaries,"BOUNDARY"],["limitations",data.limitations,"LIMITATION"]].forEach(([id,items,label])=>{const root=$(id);root.replaceChildren();items.forEach((text,index)=>{const card=document.createElement("article");card.className="boundary";add(card,"div",`${label} ${index+1}`,"eyebrow");add(card,"p",text);root.append(card);});});$("workspace").hidden=false;renderCards();}
    async function load(){try{const response=await fetch("/api/v1/data-map",{headers:{Accept:"application/json"},cache:"no-store",redirect:"error"});const data=await response.json();if(!response.ok)throw new Error(data.message||"Data map could not be loaded.");render(data);}catch(error){setStatus(error.message||"Data map could not be loaded.","bad");}}
    function reset(){state.reviewed.clear();renderCards();}function reviewNext(){const item=visibleClasses().find(entry=>!state.reviewed.has(entry.id));if(item)state.reviewed.add(item.id);renderCards();}function reviewVisible(){visibleClasses().forEach(item=>state.reviewed.add(item.id));renderCards();}async function copyReceipt(){const report=safeReceipt();const lines=["VaultLink public data map receipt",`Reviewed fixed classes: ${report.reviewed_count}/${report.class_count}`,`Scope: ${report.selected_scope_id}`,`API: ${report.api_version} | Service: ${report.service_mode} | Signed desktop: ${report.signed_desktop_version||"not published"}`,report.privacy_notice];try{await navigator.clipboard.writeText(lines.join("\n"));setStatus("Privacy-safe data map receipt copied.","good");}catch(_error){setStatus("Clipboard access was blocked by the browser.","bad");}}
    function download(name,type,text){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}function exportJson(){download("vaultlink-browser-data-map-receipt.json","application/json",JSON.stringify(safeReceipt(),null,2));setStatus("Privacy-safe browser data map receipt exported.","good");}
    $("scope").addEventListener("change",event=>{state.scope=event.target.value;renderCards();});$("reset").addEventListener("click",reset);$("next").addEventListener("click",reviewNext);$("visible").addEventListener("click",reviewVisible);$("copy").addEventListener("click",copyReceipt);$("print").addEventListener("click",()=>window.print());$("export").addEventListener("click",exportJson);load();
  </script>
</body>
</html>"""
    return page.replace("__API_VERSION__", html.escape(str(api_version), quote=True))
